// Black Ball v0.5.231203 by QuantumSuper
// glowing 2d orb centered in square shape with lighting and coloring reactive to music
// 
// - use with music in iChannel0 -

#define PI 3.14159265359 
#define aTime 150./60.*iTime
vec4 fft, ffts; //compressed frequency amplitudes


void compressFft(){ //v1.2, compress sound in iChannel0 to simplified amplitude estimations by frequency-range
    fft = vec4(0), ffts = vec4(0);

	// Sound (assume sound texture with 44.1kHz in 512 texels, cf. https://www.shadertoy.com/view/Xds3Rr)
    for (int n=0;n<3;n++) fft.x  += texelFetch( iChannel0, ivec2(n,0), 0 ).x; //bass, 0-517Hz, reduced to 0-258Hz
    for (int n=6;n<8;n++) ffts.x  += texelFetch( iChannel0, ivec2(n,0), 0 ).x; //speech I, 517-689Hz
    for (int n=8;n<14;n+=2) ffts.y  += texelFetch( iChannel0, ivec2(n,0), 0 ).x; //speech II, 689-1206Hz
    for (int n=14;n<24;n+=4) ffts.z  += texelFetch( iChannel0, ivec2(n,0), 0 ).x; //speech III, 1206-2067Hz
    for (int n=24;n<95;n+=10) fft.z  += texelFetch( iChannel0, ivec2(n,0), 0 ).x; //presence, 2067-8183Hz, tenth sample
    for (int n=95;n<512;n+=100) fft.w  += texelFetch( iChannel0, ivec2(n,0), 0 ).x; //brilliance, 8183-44100Hz, tenth2 sample
    fft.y = dot(ffts.xyz,vec3(1)); //speech I-III, 517-2067Hz
    ffts.w = dot(fft.xyzw,vec4(1)); //overall loudness
    fft /= vec4(3,8,8,5); ffts /= vec4(2,3,3,23); //normalize

	//for (int n=0;n++<4;) fft[n] *= 1. + .3*pow(fft[n],5.); fft = clamp(fft,.0,1.); //limiter? workaround attempt for VirtualDJ
}

mat2 rotM(float r){float c = cos(r), s = sin(r); return mat2(c,s,-s,c);} //2D rotation matrix

vec3 tmUnreal( vec3 c){return c / (c + .155) * 1.019;} //tone map, source: https://www.shadertoy.com/view/llXyWr

float aaStep( float fun){return smoothstep( fwidth(fun), .0, fun);} //simple antialiasing

float glow( float sd, float amp){return clamp( amp / max( amp, sd), .0 ,1.);} //simple glow

float sdBox( vec2 p, vec2 b){ //source: https://iquilezles.org/articles/distfunctions2d/
    vec2 d = abs(p) - b;
    return length(max(d,.0)) + min(max(d.x,d.y),.0);
}

vec3 getCol(float id){ //fork of v0.8, color definitions, for pairs, with color shift
    vec3 setCol = vec3(0);
    id = fract(id/8.)*8.;// mod(id,8.);
         if (id< 1.) setCol = vec3( 23,123,250); //cneon blue
    else if (id< 2.) setCol = vec3( 30, 29,215); //vw2 blue
    else if (id< 3.) setCol = vec3(244,  0,204); //vw2 pink
    else if (id< 4.) setCol = vec3(131, 58,187); //nordic violet
    else if (id< 5.) setCol = vec3(  0,250,253); //vw2 light blue
    else if (id< 6.) setCol = vec3( 66,120, 91); //matrix green 2
    else if (id< 7.) setCol = vec3(252,157,  0); //miami orange
    else if (id< 8.) setCol = vec3(231, 15, 20); //arena red
    setCol *= abs(cos(.06*aTime + PI/vec3(.5,2.,4.) + ffts.xyz)); //color shift
    return setCol/256.;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = (2.*fragCoord-iResolution.xy) / max(iResolution.x, iResolution.y); //long edge -1 to 1, square aspect ratio 
    compressFft(); //initializes fft, ffts
    vec2 uv0=uv;


    // Design
    float size = 1./exp(cos(aTime/8.)*2.+3.);
    uv *= mix( 1., .5 + 1.*texelFetch( iChannel0, ivec2(mod(dot(floor((uv)/size),vec2(1,1./size)),512.),0), 0).x, fft.w*fft.w*fft.w); //pixel shift

    float mySd = sdBox( uv*rotM( PI/4.), vec2(.66*(.97+.03*fft.z))); //square definition
    vec3 col = vec3(glow( mySd, .01) - aaStep( mySd)) * (1.3-fft.y) 
        * texelFetch( iChannel0, ivec2((floor(abs(uv.y)*22.)+floor(abs(uv.x)*22.)/22.)/22.*512.,0), 0).x * 2. ; //square visualization bw

    if (fft.x<.94) uv = uv0; //conditional pixel shift
    mySd = length(uv)-.3*(.4+.6*fft.x*fft.x*fft.x); //circle definition
    col += (glow( mySd, .01) - aaStep( mySd)) * (.2+.8*fft.x); //circle visualization bw

    float colId = floor(aTime/32.)*2.; //color identifier
    float amp = (aaStep( mySd)*.93 + .07); //colorization intensities 
    col += clamp( uv.y+(fft.y*fft.y-.5)*.2, .0, 1.) * getCol(colId+0.) * amp * ffts.w; //top light color
    col += clamp( sign(fract(aTime/64.-.25)-.5)*uv.x + sin(aTime/64.*PI*2.)*.6 + .3, .0, 1.) * getCol(colId+1.) * amp * fft.w; //"rotating" moonrise light color

    mySd = abs(mySd+.001) - (1.-uv.y*uv.y*111.)*.001; //edge ring definition
    col += col * glow( mySd, .01)  * 9.; //edge ring visualization

    if (fft.x>.97) //max bass
        col += col * fract(float(iFrame)*.5)*9.; //strobo


    // Finalization
	col -= length(uv) * .01; //vignette
    col = tmUnreal( col); //tone map incl. gamma

    fragColor = vec4(col,1.);
}
